// Board assets. The files live in src/assets (generated by scripts/optimize-assets.sh from art/), so Vite
// fingerprints their names and nginx can cache them forever. Drei's loaders cache by URL list, so preloadBoard
// must make the same calls as the board: one URL per call (one failed tile then only costs that tile).
import { useGLTF, useTexture } from '@react-three/drei';
import * as THREE from 'three';
import { tokenKey } from '../../lib/tokens';

const fileName = path => path.split('/').pop().replace(/\.[^.]+$/, '');

const textureFiles = import.meta.glob('../../assets/board/*.webp', { eager: true, query: '?url', import: 'default' });
const tokenFiles = import.meta.glob('../../assets/tokens/*.glb', { eager: true, query: '?url', import: 'default' });

const textures = Object.fromEntries(Object.entries(textureFiles).map(([path, url]) => [fileName(path), url]));

export const BOARD_URL = textures.board;
export const TILE_URLS = Object.fromEntries(Object.entries(textures).filter(([key]) => key !== 'board'));
export const TOKEN_URLS = Object.fromEntries(Object.entries(tokenFiles).map(([path, url]) => [fileName(path), url]));

// Self-hosted Draco decoder (public/draco, copied from three by optimize-assets.sh). Drei's default is the
// gstatic CDN, which fails offline and on networks that block it.
export const DRACO_PATH = `${import.meta.env.BASE_URL}draco/`;

/** Art file key for a space name: "Hell's Kitchen" -> "hellskitchen". */
export function tileKey(name) {
  return name.toLowerCase().replace(/'/g, '').replace(/&/g, 'and').replace(/\s+/g, '');
}

export function tokenUrl(tokenType) {
  return TOKEN_URLS[tokenKey(tokenType)] ?? TOKEN_URLS.taxi;
}

/** Same arguments as the Token component's useGLTF call, so the cache is shared. */
export function useTokenModel(url) {
  return useGLTF(url, DRACO_PATH, false);
}

/** Drop a failed model download from the cache, so the next attempt fetches it again. */
export function clearTokenModel(url) {
  useGLTF.clear(url);
}

/** Texture setup for tiles and the centre art (runs once per load, before upload). */
export function setupTextures(input) {
  const list = Array.isArray(input) ? input : input?.isTexture ? [input] : Object.values(input || {});
  for (const t of list) {
    t.colorSpace = THREE.SRGBColorSpace;
    t.anisotropy = 8; // three clamps this to what the GPU supports; 1 smears the far row
    t.needsUpdate = true;
  }
}

/**
 * Start downloading everything the board needs (call it from the lobby, before the game screen mounts).
 * Pass the token types in play to skip models nobody uses.
 */
export function preloadBoard(tokenTypes) {
  useTexture.preload(BOARD_URL);
  Object.values(TILE_URLS).forEach(url => useTexture.preload(url));
  const urls = tokenTypes?.length ? [...new Set(tokenTypes.map(tokenUrl))] : Object.values(TOKEN_URLS);
  urls.forEach(url => useGLTF.preload(url, DRACO_PATH, false));
}
